use std::sync::{mpsc, Arc, Condvar, Mutex};
use std::thread;

fn main() {
    let p = Arc::new((Mutex::new(false), Condvar::new()));
    let mut hs = vec![];
    for _ in 0..2 {
        let q = Arc::clone(&p);
        hs.push(thread::spawn(move || {
            let (m, cv) = &*q;
            let mut g = m.lock().unwrap();
            while !*g {
